s=s.replace('DispatchDecision, EmployeeAccount, Fleet, Order, Restaurant, Rider, RiderApplication, RiderIncident, RiderSlot, Zone, ensureIndexes', 'DispatchDecision, EmployeeAccount, Fleet, Order, Restaurant, Rider, RiderApplication, RiderIncident, RiderSlot, Zone, PasskeyCredential, RiderAssignmentReservation, ensureIndexes')
