insert='''const locationCache = new Map<string, { expiresAt: number; data: unknown }>();\napp.get("/api/v1/locations/search", async (req, res) => {\n  const q = typeof req.query.q === "string" ? req.query.q.trim() : "";\n  if (q.length < 3) return res.json({ results: [] });\n  const key = q.toLocaleLowerCase("es"); const cached = locationCache.get(key); if (cached && cached.expiresAt > Date.now()) return res.json({ results: cached.data });\n  try {\n    const url = new URL("https://nominatim.openstreetmap.org/search"); url.searchParams.set("format", "jsonv2"); url.searchParams.set("addressdetails", "1"); url.searchParams.set("limit", "12"); url.searchParams.set("countrycodes", "es"); url.searchParams.set("q", `${q}, Comunidad Valenciana, España`);\n    const response = await fetch(url, { headers: { "User-Agent": "PIKI-Delivery/1.0 contacto@pikidelivery.com", Accept: "application/json" } });\n    if (!response.ok) return res.json({ results: [] });\n    const raw = await response.json() as any[]; const results = raw.map((item) => ({ label: item.display_name, latitude: Number(item.lat), longitude: Number(item.lon), type: item.type, address: item.address || {} })).filter((item) => Number.isFinite(item.latitude) && Number.isFinite(item.longitude));\n    locationCache.set(key, { expiresAt: Date.now() + 10 * 60_000, data: results }); return res.json({ results });\n  } catch { return res.json({ results: [] }); }\n});\n\nfunction getCustomerSession(req: express.Request) { const cookie = req.header("cookie")?.split(";").map((part) => part.trim()).find((part) => part.startsWith("piki_customer_session=")); return cookie?.slice("piki_customer_session=".length) || null; }\nasync function getCustomerBySession(req: express.Request) { const raw = getCustomerSession(req); return raw ? (await (await import("./models.js")).CustomerAccount.findOne({ sessionHash: hashSessionToken(raw) }).lean().exec() as any) : null; }\napp.post("/api/v1/passkeys/customer/register/options", async (req, res) => { const owner = await getCustomerBySession(req); if (!owner) return res.status(401).json({ error: "CUSTOMER_LOGIN_REQUIRED" }); return registrationOptions(req, res, "customer", owner); });\napp.post("/api/v1/passkeys/customer/register/verify", async (req, res) => { const owner = await getCustomerBySession(req); if (!owner) return res.status(401).json({ error: "CUSTOMER_LOGIN_REQUIRED" }); return verifyRegistration(req, res, "customer", owner); });\napp.post("/api/v1/passkeys/customer/auth/options", async (req, res) => authenticationOptions(req, res, "customer"));\napp.post("/api/v1/passkeys/customer/auth/verify", async (req, res) => { const result = await verifyAuthentication(req, res, "customer"); if (res.headersSent || !result) return; const owner = await (await import("./models.js")).CustomerAccount.findById(result.ownerId).lean().exec() as any; if (!owner) return res.status(404).json({ error: "CUSTOMER_NOT_FOUND" }); const raw = createSessionToken(); await (await import("./models.js")).CustomerAccount.updateOne({ _id: owner._id }, { $set: { sessionHash: hashSessionToken(raw), lastSignedIn: new Date() } }).exec(); res.setHeader("Set-Cookie", `piki_customer_session=${raw}; Max-Age=31536000; Path=/; HttpOnly; Secure; SameSite=None`); return res.json({ verified: true, user: { id: owner._id, name: owner.name, email: owner.email, role: "user" } }); });\n\n'''
if '/api/v1/locations/search' not in s: s=s.replace(marker,insert+marker)
old='''  for (const decision of ranked) {\n    const currentLoad = counts.get(decision.riderId) || 0;\n    const riderUpdate = currentLoad === 0 ? { $set: { status: "busy", activeOrderId: order._id } } : { $set: { status: "busy" } };\n    const riderFilter = currentLoad === 0 ? { _id: objectId(decision.riderId), status: { $in: ["available", "busy"] }, activeOrderId: null } : { _id: objectId(decision.riderId), status: { $in: ["available", "busy"] }, activeOrderId: { $ne: null } };\n    const rider = await Rider.findOneAndUpdate(riderFilter, riderUpdate, { new: true }).lean().exec() as any;\n    if (!rider) continue;\n    const expiresAt = new Date(Date.now() + parsed.data.offerSeconds * 1000);\n    const assigned = await Order.findOneAndUpdate({ _id: order._id, riderId: null, assignmentState: { $in: ["unassigned", "expired", "rejected"] } }, { $set: { riderId: rider._id, assignmentState: "offered", assignmentExpiresAt: expiresAt, dispatchScore: decision.score }, $inc: { dispatchAttempts: 1, version: 1 } }, { new: true }).lean().exec() as any;\n    if (!assigned) { await Rider.updateOne({ _id: rider._id, activeOrderId: order._id }, { $set: { status: "available", activeOrderId: null } }).exec(); continue; }\n    await DispatchDecision.create({ orderId: assigned._id, ...decision, riderId: rider._id, outcome: "offered", actorRole: req.auth?.role || "system" });\n    return res.status(201).json({ assignment: { orderId: assigned._id, riderId: rider._id, state: assigned.assignmentState, expiresAt, score: decision.score, pickupDistanceKm: decision.pickupDistanceKm, pickupEtaMinutes: decision.pickupEtaMinutes, customerEtaMinutes: decision.customerEtaMinutes, totalEtaMinutes: decision.totalEtaMinutes, algorithmVersion: decision.algorithmVersion, maxConcurrentOrders: policy.maxConcurrentOrders, saturated: policy.saturated, reasons: decision.reasons } });\n  }'''
new='''  for (const decision of ranked) {\n    const riderId = objectId(decision.riderId); if (!riderId) continue;\n    const session = await mongoose.startSession();\n    try {\n      let assigned: any = null; let rider: any = null; const expiresAt = new Date(Date.now() + parsed.data.offerSeconds * 1000);\n      await session.withTransaction(async () => {\n        const reserved = await RiderAssignmentReservation.countDocuments({ riderId, status: "reserved" }).session(session);\n        if (reserved >= policy.maxConcurrentOrders) return;\n        rider = await Rider.findOneAndUpdate({ _id: riderId, status: { $in: ["available", "busy"] }, ...(reserved === 0 ? { activeOrderId: null } : {}) }, { $set: { status: "busy", ...(reserved === 0 ? { activeOrderId: order._id } : {}) } }, { new: true, session }).lean().exec();\n        if (!rider) return;\n        const slot = reserved + 1;\n        await RiderAssignmentReservation.create([{ riderId, orderId: order._id, slot, mode: policy.saturated ? "saturated" : "normal", status: "reserved", expiresAt }], { session });\n        assigned = await Order.findOneAndUpdate({ _id: order._id, riderId: null, assignmentState: { $in: ["unassigned", "expired", "rejected"] } }, { $set: { riderId, assignmentState: "offered", assignmentExpiresAt: expiresAt, dispatchScore: decision.score }, $inc: { dispatchAttempts: 1, version: 1 } }, { new: true, session }).lean().exec();\n        if (!assigned) throw new Error("ORDER_RESERVATION_RACE");\n      });\n      if (!assigned || !rider) continue;\n      await DispatchDecision.create({ orderId: assigned._id, ...decision, riderId, outcome: "offered", actorRole: req.auth?.role || "system" });\n      return res.status(201).json({ assignment: { orderId: assigned._id, riderId, slot: await RiderAssignmentReservation.findOne({ orderId: assigned._id }).select("slot mode").lean().exec(), state: assigned.assignmentState, expiresAt, score: decision.score, pickupDistanceKm: decision.pickupDistanceKm, pickupEtaMinutes: decision.pickupEtaMinutes, customerEtaMinutes: decision.customerEtaMinutes, totalEtaMinutes: decision.totalEtaMinutes, algorithmVersion: decision.algorithmVersion, maxConcurrentOrders: policy.maxConcurrentOrders, saturated: policy.saturated, reasons: decision.reasons } });\n    } catch (error) { if (error instanceof Error && error.message === "ORDER_RESERVATION_RACE") continue; if ((error as any)?.code === 11000) continue; throw error; } finally { await session.endSession(); }\n  }'''
if old not in s: print('ASSIGN_BLOCK_NOT_FOUND')
